codashop.cssOverride:
[data-theme='fcm'] {
  --x-ref-primary: oklch(0.803 0.225 149.2); /* #05E466 */
  --x-ref-secondary: oklch(0.948 0.22 117); /* #E5FF00 */
  --x-ref-tertiary: oklch(0.905 0.155 194.8); /* #00FFFF */
  --x-ref-neutral: oklch(0.158 0.002 197); /* #0C0D0D */
  --x-ref-status-positive: oklch(0.723 0.192 149.6); /* #22C55E */
  --x-ref-status-caution: oklch(0.769 0.165 70.1); /* #F59E0B */
  --x-ref-status-negative: oklch(0.637 0.208 25.3); /* #EF4444 */
  --x-sys-font-family-heading: 'Cruyff Sans', 'Inter', system-ui, sans-serif;
  --x-sys-font-family-body: 'Cruyff Sans', 'Inter', system-ui, sans-serif;
  --x-sys-font-condense: 1;
}
html[data-theme='fcm'] {
  --x-radius-control-full: var(--x-sys-radius-full); /* 999px pill, overrides the 2px system default */
}
